head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil51040";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.listTpClssCd, param.ldMktTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil51040.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(((String(dma_defaultMap.get("listTpClssCd")) === "02") ? "상장법인" : "심사진행법인")); } },
        { childId: "__rb1", attr: "label", fn: function () { return String(dma_defaultMap.get("comNm")) + "(" + String(dma_defaultMap.get("isurCd")) + ")"; } },
        { childId: "__rb2", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_defaultMap.get("mktTpNm")); } },
        { childId: "__rb4", attr: "label", fn: function () { return String(dma_defaultMap.get("secugrpNm")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_listTpClssCd_3", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "if_listTpClssCd_4", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") !== '07'); } }, { id: "if_listTpClssCd_5", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "if_listTpClssCd_6", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") !== '07'); } }, { id: "if_listTpClssCd_7", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "if_listTpClssCd_8", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") !== '07'); } }, { id: "if_listTpClssCd_9", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "if_listTpClssCd_10", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") !== '07'); } }, { id: "if_listTpClssCd_11", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "if_listTpClssCd_12", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") !== '07'); } }, { id: "if_listTpClssCd_13", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "if_listTpClssCd_14", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") !== '07'); } }, { id: "if_listTpClssCd_15", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "if_listTpClssCd_16", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") !== '07'); } }, { id: "if_listTpClssCd_17", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "if_listTpClssCd_18", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") !== '07'); } }, { id: "if_listTpClssCd_19", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "if_listTpClssCd_20", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") !== '07'); } }, { id: "if_lgshrhdNm", fn: function(){ return ((dma_comInfo.get("lgshrhdNm") ?? (() => { throw new Error("unresolved:" + "comInfo.lgshrhdNm"); })()) !==''); } }, { id: "if_ovr1pctOwnrNm", fn: function(){ return ((dma_comInfo.get("ovr1pctOwnrNm") ?? (() => { throw new Error("unresolved:" + "comInfo.ovr1pctOwnrNm"); })()) !==''); } }, { id: "if_listTpClssCd_21", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "if_listTpClssCd_22", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") !== '07'); } }, { id: "if_listTpClssCd_23", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "tr_271", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '00'); } }, { id: "if_ldMktTpCd", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") ==='2'); } }, { id: "btn_Register", fn: function(){ return ((dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 32 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 33 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 34 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 36); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_sum1", fn: function () { return String((String(dma_comInfo.get("lgshrhdCmstkShrs")) + String(dma_comInfo.get("lgshrhdPrefstkShrs")))); } },
        { childId: "ipt_sum2", fn: function () { return String((String(dma_comInfo.get("lgshrhdRelprnCmstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnPrefstkShrs")))); } },
        { childId: "ipt_sum3", fn: function () { return String((String(dma_comInfo.get("lgshrhdCmstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnCmstkShrs")))); } },
        { childId: "ipt_sum4", fn: function () { return String((String(dma_comInfo.get("lgshrhdPrefstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnPrefstkShrs")))); } },
        { childId: "ipt_sum5", fn: function () { return String(((String(dma_comInfo.get("lgshrhdCmstkShrs")) + String(dma_comInfo.get("lgshrhdPrefstkShrs"))) + (String(dma_comInfo.get("lgshrhdRelprnCmstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnPrefstkShrs"))))); } },
        { childId: "ipt_sum6", fn: function () { return String((String(dma_comInfo.get("lgshrhdShrRt")) + String(dma_comInfo.get("lgshrhdRelprnShrRt")))); } },
        { childId: "ipt_sum7", fn: function () { return String((String(dma_comInfo.get("lgshrhdBfpubofrSaleShrs")) + String(dma_comInfo.get("lssrpBfpubofrSaleShrs")))); } },
        { childId: "ipt_sum8", fn: function () { return String((String(dma_comInfo.get("lgshrhdBfpubofrOferShrs")) + String(dma_comInfo.get("lssrpBfpubofrOferShrs")))); } },
        { childId: "ipt_sum9", fn: function () { return String((String(dma_comInfo.get("lgshrhdAfpubofrShrs")) + String(dma_comInfo.get("lssrpAfpubofrShrs")))); } },
        { childId: "ipt_sum10", fn: function () { return String((String(dma_comInfo.get("lgshrhdAfpubofrShrRt")) + String(dma_comInfo.get("lssrpAfpubofrShrRt")))); } },
        { childId: "ipt_sum11", fn: function () { return String((String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctPrefstkShrs")))); } },
        { childId: "ipt_sum12", fn: function () { return String((String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs")))); } },
        { childId: "ipt_sum13", fn: function () { return String((String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")))); } },
        { childId: "ipt_sum14", fn: function () { return String((String(dma_comInfo.get("ovr1pctPrefstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs")))); } },
        { childId: "ipt_sum15", fn: function () { return String(((String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctPrefstkShrs"))) + (String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs"))))); } },
        { childId: "ipt_sum16", fn: function () { return String((String(dma_comInfo.get("ovr1pctShrRt")) + String(dma_comInfo.get("ovr1pctRelprnShrRt")))); } },
        { childId: "ipt_sum17", fn: function () { return String((String(dma_comInfo.get("ovr1pctBfpubofrSaleShrs")) + String(dma_comInfo.get("o1psrpBfpubofrSaleShrs")))); } },
        { childId: "ipt_sum18", fn: function () { return String((String(dma_comInfo.get("ovr1pctBfpubofrOferShrs")) + String(dma_comInfo.get("o1psrpBfpubofrOferShrs")))); } },
        { childId: "ipt_sum19", fn: function () { return String((String(dma_comInfo.get("ovr1pctAfpubofrShrs")) + String(dma_comInfo.get("o1psrpAfpubofrShrs")))); } },
        { childId: "ipt_sum20", fn: function () { return String((String(dma_comInfo.get("ovr1pctAfpubofrShrRt")) + String(dma_comInfo.get("o1psrpAfpubofrShrRt")))); } },
        { childId: "ipt_sum21", fn: function () { return String((String(dma_comInfo.get("minshrhdCmstkShrs")) + String(dma_comInfo.get("minshrhdPrefstkShrs")))); } },
        { childId: "ipt_sum23", fn: function () { return String(((String(dma_comInfo.get("minshrhdCmstkShrs")) + (String(dma_comInfo.get("lgshrhdCmstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnCmstkShrs")))) + (String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnCmstkShrs"))))); } },
        { childId: "ipt_sum24", fn: function () { return String(((String(dma_comInfo.get("minshrhdPrefstkShrs")) + (String(dma_comInfo.get("lgshrhdPrefstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnPrefstkShrs")))) + (String(dma_comInfo.get("ovr1pctPrefstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs"))))); } },
        { childId: "ipt_sum25", fn: function () { return String((((((String(dma_comInfo.get("minshrhdCmstkShrs")) + String(dma_comInfo.get("minshrhdPrefstkShrs"))) + (String(dma_comInfo.get("lgshrhdCmstkShrs")) + String(dma_comInfo.get("lgshrhdPrefstkShrs")))) + (String(dma_comInfo.get("lgshrhdRelprnCmstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnPrefstkShrs")))) + (String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctPrefstkShrs")))) + (String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs"))))); } },
        { childId: "ipt_sum26", fn: function () { return String(((((String(dma_comInfo.get("minshrhdShrRt")) + String(dma_comInfo.get("ovr1pctShrRt"))) + String(dma_comInfo.get("ovr1pctRelprnShrRt"))) + String(dma_comInfo.get("lgshrhdShrRt"))) + String(dma_comInfo.get("lgshrhdRelprnShrRt")))); } },
        { childId: "ipt_sum27", fn: function () { return String(((((String(dma_comInfo.get("lgshrhdBfpubofrSaleShrs")) + String(dma_comInfo.get("lssrpBfpubofrSaleShrs"))) + String(dma_comInfo.get("ovr1pctBfpubofrSaleShrs"))) + String(dma_comInfo.get("o1psrpBfpubofrSaleShrs"))) + String(dma_comInfo.get("minshrhdBfpubofrSaleShrs")))); } },
        { childId: "ipt_sum28", fn: function () { return String(((((String(dma_comInfo.get("lgshrhdBfpubofrOferShrs")) + String(dma_comInfo.get("lssrpBfpubofrOferShrs"))) + String(dma_comInfo.get("ovr1pctBfpubofrOferShrs"))) + String(dma_comInfo.get("o1psrpBfpubofrOferShrs"))) + String(dma_comInfo.get("minshrhdBfpubofrOferShrs")))); } },
        { childId: "ipt_sum29", fn: function () { return String((((String(dma_comInfo.get("minshrhdAfpubofrShrs")) + (String(dma_comInfo.get("lgshrhdAfpubofrShrs")) + String(dma_comInfo.get("lssrpAfpubofrShrs")))) + String(dma_comInfo.get("ovr1pctAfpubofrShrs"))) + String(dma_comInfo.get("o1psrpAfpubofrShrs")))); } },
