/**
 * @method
 * @name checkRate
 * @description check Rate 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkRate = async function (obj) {
    let result = obj.value;
    if (result === "") {
        result = "0";
    }
    result = Number(result.split(",").join(""));
    if (result > 100) {
        await $c.win.alert("100% 이하여야합니다.");
        obj.focus();
    }
};

