/**
 * @method
 * @name makeNum
 * @description make Num 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.makeNum = function (val) {
    let result = (document.preListForm || { elements: [] })[val].value;
    if (result === "") {
        result = "0";
    }
    result = result.split(",").join("");
    result = Number(result);
    return result;
};

/**
 * @method
 * @name checkMoney
 * @description check Money 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMoney = async function (obj) {
    let result = obj.value;
    if (result === "") {
        result = "0";
    }
    result = Number(result.split(",").join(""));
    if (result > 1000000000) {
        await $c.win.alert("1,000,000,000 미만이어야 합니다.");
        obj.focus();
    }
};
